def f(g):
    gs=comps(g)
    # family groups by normalized shape; take each group's bbox union? Use largest group
    grp=defaultdict(list)
    for c in gs:
        rm=tuple(sorted((p[0]-min(p[0] for p in c),p[1]-min(p[1] for p in c)) for p in c))
        grp[rm].append(c)
    fam=max(grp.items(),key=lambda kv:len(kv[1]))
    clones=fam[1]
    # output = count canvas over the bbox of ALL clone copies, value=number of cells covered
    rs=[min(p[0] for p in cl) for cl in clones]
    cs=[min(p[1] for p in cl) for cl in clones]
    r0,c0=min(rs),min(cs)
    H=max(rs)-r0+1; W=max(cs)-c0+1
    cnt=[[0]*W for _ in range(H)]
    for cl in clones:
        rr=min(p[0] for p in cl); cc=min(p[1] for p in cl)
        for a,b in cl:
            if 0<=a-rr+r0<H and 0<=b-cc+c0<W:
                cnt[a-rr+r0][b-cc+c0]+=1
    return [[min(cnt[r][c],1) if cnt[r][c]>0 else 0 for c in range(W)] for r in range(H)]
