    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
# Hypothesis: all big comps are noisy copies of one template. Template = pattern appearing as a SUBBLOCK (any placement within bbox) in the MOST comps. Count per candidate mask.
from collections import Counter
def get_comps(g):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx] and (ny,nx) not in seen: stack.append((ny,nx))
                out.append(comp)
    return out
ti=G['Test input']
comps=get_comps(ti)
big=[c for c in comps if len(c)>1]
print('test big comps:',[(min(p[0] for p in c),min(p[1] for p in c),max(p[0] for p in c)-min(p[0] for p in c)+1,max(p[1] for p in c)-min(p[1] for p in c)+1,len(c)) for c in big])
# For each comp, its mask; count how many other comps contain it as a subblock (aligned anywhere inside their bbox)
counts=Counter()
for i,A in enumerate(big):
    r0=min(p[0] for p in A); c0=min(p[1] for p in A)
    h=max(p[0] for p in A)-r0+1; w=max(p[1] for p in A)-c0+1
    mA=[[ti[r0+a][c0+b]!=0 for b in range(w)] for a in range(h)]
    nb=sum(map(sum,mA))
    total=0
    for B in big:
        r1=min(p[0] for p in B); c1=min(p[1] for p in B)
        bh=max(p[0] for p in B)-r1+1; bw=max(p[1] for p in B)-c1+1
        if bh>=h and bw>=w:
            tot=0
            for dy in range(bh-h+1):
                for dx in range(bw-w+1):
                    if all(mA[a][b]==(ti[r1+dy+a][c1+dx+b]!=0) for a in range(h) for b in range(w)):
                        tot+=1
            if tot: total+=tot
    counts[(nb,total,r0,c0,h,w)]=total
print(counts.most_common(10))

